#!/usr/bin/env python3
import csv, gzip, io, json, os, sys
from datetime import datetime, timedelta, timezone, date
from fractions import Fraction
from zoneinfo import ZoneInfo

UTC = timezone.utc


def read_text(path):
    with open(path, 'rb') as f:
        data = f.read()
    if data[:2] == b'\x1f\x8b':
        data = gzip.decompress(data)
    return data.decode('utf-8-sig')


def lines_of(text):
    for ln in text.split('\n'):
        ln = ln.rstrip('\r')
        if ln.strip() == '':
            continue
        yield ln


def local_to_epoch(naive, zone, dst=None, std_offset=None):
    """naive local datetime -> epoch seconds. dst: True/False/None for ambiguous times."""
    if std_offset is not None:
        return int((naive - std_offset).replace(tzinfo=UTC).timestamp())
    a = naive.replace(tzinfo=zone, fold=0)
    b = naive.replace(tzinfo=zone, fold=1)
    if a.utcoffset() != b.utcoffset():
        # ambiguous (or gap); first occurrence is the DST one
        if dst is False:
            return int(b.timestamp())
        return int(a.timestamp())
    return int(a.timestamp())


def std_offset_of(zone, naive):
    d = naive.replace(tzinfo=zone, fold=1)
    return d.utcoffset() - (d.dst() or timedelta(0))


def parse_offset(s):
    sign = -1 if s[0] == '-' else 1
    return sign * timedelta(hours=int(s[1:3]), minutes=int(s[3:5]))


def csv_rows(text, delim=','):
    return list(csv.reader([l for l in lines_of(text)], delimiter=delim))


def parse_abbr(text, zone):
    out = []
    hdr = None
    for row in csv_rows(text):
        cells = [c.strip() for c in row]
        if 'Badge' in cells and 'Punch' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        t = g('Time').upper()
        ampm = None
        if t.endswith('AM') or t.endswith('PM'):
            ampm = t[-2:]
            t = t[:-2].strip()
        h, m, s = (int(x) for x in t.split(':'))
        if ampm:
            h = h % 12 + (12 if ampm == 'PM' else 0)
        mo, d, y = (int(x) for x in g('Date').split('/'))
        naive = datetime(y, mo, d, h, m, s)
        ab = g('Zone').upper()
        dst = True if ab.endswith('DT') else False if ab.endswith('ST') else None
        out.append((g('Record'), g('Badge'), g('Punch').upper(), local_to_epoch(naive, zone, dst)))
    return out


