    out = []
    schema = 1
    for ln in lines_of(text):
        o = json.loads(ln)
        if 'schema' in o and 'heartbeat' not in o and 'id' not in o and 'punch_id' not in o:
            schema = o['schema']
            continue
        if o.get('heartbeat'):
            continue
        if schema == 2:
            pid, emp, d, ts = o['punch_id'], o['employee'], o['direction'], int(o['epoch_ms']) // 1000
        else:
            pid, emp, d = o['id'], o['emp'], o['dir']
            ts = int(o['ts']) if 'ts' in o else int(o['ts_ms']) // 1000
        out.append((str(pid), str(emp).strip(), d.upper(), ts))
    return out


def parse_offset_csv(text):
    out = []
    hdr = None
    for row in csv_rows(text, ';'):
        cells = [c.strip() for c in row]
        if 'punch_id' in cells and 'timestamp' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        ts = datetime.fromisoformat(g('timestamp')).astimezone(UTC)
        d = 'IN' if g('event') == 'clock_in' else 'OUT'
        out.append((g('punch_id'), g('employee'), d, int(ts.timestamp())))
    return out


def parse_legacy(text, zone):
    out = []
    off = None
    for ln in lines_of(text):
        t = ln[0]
        if t == 'H':
            o = ln[13:18].strip()
            off = parse_offset(o) if o else None
        elif t == 'D':
            pid = ln[1:9]
            badge = ln[9:15].strip()
            emp = 'E' + badge
            d = 'IN' if ln[15] == 'I' else 'OUT'
            dt = ln[16:30]
            naive = datetime(int(dt[0:4]), int(dt[4:6]), int(dt[6:8]), int(dt[8:10]), int(dt[10:12]), int(dt[12:14]))
            so = off if off is not None else std_offset_of(zone, naive)
            out.append((pid, emp, d, local_to_epoch(naive, zone, std_offset=so)))
    return out


def parse_de(text, zone):
    out = []
    hdr = None
    for row in csv_rows(text, '\t'):
        cells = [c.strip() for c in row]
        if 'Ausweis' in cells and 'Buchung' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        dd, mm, yy = (int(x) for x in g('Datum').split('.'))
        hh, mi = (int(x) for x in g('Uhrzeit').split(':')[:2])
        naive = datetime(yy, mm, dd, hh, mi)
        z = g('Zeitzone').upper()
        dst = True if z == 'MESZ' else False if z == 'MEZ' else None
        out.append((g('Nr'), g('Ausweis'), 'IN' if g('Buchung') == 'K' else 'OUT', local_to_epoch(naive, zone, dst)))
    return out


def parse_local_csv(text, zone):
    out = []
    hdr = None
    for row in csv_rows(text):
        cells = [c.strip() for c in row]
        if 'employee_id' in cells and 'local_time' in cells:
            hdr = {n: i for i, n in enumerate(cells)}
            continue
        if hdr is None:
            continue
        g = lambda n: cells[hdr[n]]
        naive = datetime.strptime(g('local_time'), '%Y-%m-%d %H:%M:%S')
        out.append((g('punch_ref'), g('employee_id'), g('direction').upper(), local_to_epoch(naive, zone, True)))
    return out


def parse_local_jsonl(text, zone):
    out = []
    for ln in lines_of(text):
        o = json.loads(ln)
        p = o.get('punch')
        if not isinstance(p, dict):
            continue
        pid = p['id']
        pid = str(int(pid)) if isinstance(pid, (int, float)) else str(pid)
        naive = datetime.strptime(p['at'], '%Y-%m-%d %H:%M:%S')
        out.append((pid, str(p['badge']).strip(), p['type'].upper(), local_to_epoch(naive, zone, True)))
    return out


def round_punch(ts, zone):
    off = int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())
    ls = ts + off
    r = (ls + 180) // 360 * 360
    return r - off


def offset_at(ts, zone):
    return int(datetime.fromtimestamp(ts, UTC).astimezone(zone).utcoffset().total_seconds())


def local_date(ts, zone):
    return datetime.fromtimestamp(ts, UTC).astimezone(zone).date()


def night_minutes(a, b, zone):
    """minutes in [a,b] (epoch) between 22:00 and 06:00 local, elapsed time."""
    if b <= a:
        return 0
    total = 0
    # split at offset changes by walking in hour chunks only when offsets differ
    oa, ob = offset_at(a, zone), offset_at(b, zone)
    segs = []
    if oa == ob and offset_at((a + b) // 2, zone) == oa:
        segs = [(a, b, oa)]
    else:
        t = a
        while t < b:
            n = min(b, t + 60)
            segs.append((t, n, offset_at(t, zone)))
            t = n
    for s, e, off in segs:
        ls, le = s + off, e + off
        k = ls // 86400 - 1
        while k * 86400 - 7200 < le:
            lo, hi = k * 86400 - 7200, k * 86400 + 21600
            ov = min(hi, le) - max(lo, ls)
            if ov > 0:
                total += ov
            k += 1
    return total // 60


