    cutoff = datetime.fromisoformat(period['corrections_cutoff'].replace('Z', '+00:00')).timestamp()

    sites = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'sites.csv')))):
        sites[r['site'].strip()] = (ZoneInfo(r['timezone'].strip()), r['format'].strip())
    employees = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'employees.csv')))):
        employees[r['employee_id'].strip()] = r['home_site'].strip()
    rates = {}
    for r in csv.DictReader(io.StringIO(read_text(os.path.join(inp, 'rates.csv')))):
        rates.setdefault(r['employee_id'].strip(), []).append(
            (date.fromisoformat(r['effective_from'].strip()), Fraction(r['hourly_rate'].strip())))
    for v in rates.values():
        v.sort()

    # 1. collect
    punches = {}  # (site, id) -> [emp, dir, ts]
    ever = set()
    for site, (zone, fmt) in sites.items():
        d = os.path.join(inp, 'exports', site)
        if not os.path.isdir(d):
            continue
        for root, _, files in os.walk(d):
            for fn in sorted(files):
                text = read_text(os.path.join(root, fn))
                if fmt == 'abbr-csv':
                    recs = parse_abbr(text, zone)
                elif fmt == 'epoch-jsonl':
                    recs = parse_epoch(text)
                elif fmt == 'offset-csv':
                    recs = parse_offset_csv(text)
                elif fmt == 'legacy-fixed':
                    recs = parse_legacy(text, zone)
                elif fmt == 'de-tsv':
                    recs = parse_de(text, zone)
                elif fmt == 'local-csv':
                    recs = parse_local_csv(text, zone)
                elif fmt == 'local-jsonl':
                    recs = parse_local_jsonl(text, zone)
                else:
                    raise SystemExit('unknown format ' + fmt)
                for pid, emp, dr, ts in recs:
                    k = (site, pid)
                    ever.add(k)
                    if k not in punches:
                        punches[k] = [emp, dr, ts]

    # 2. corrections
    corr = []
    cdir = os.path.join(inp, 'corrections')
    if os.path.isdir(cdir):
        for root, _, files in os.walk(cdir):
            for fn in files:
                for r in csv.DictReader(io.StringIO(read_text(os.path.join(root, fn)))):
                    r = {k.strip(): (v or '').strip() for k, v in r.items() if k}
                    r['_at'] = datetime.fromisoformat(r['issued_at'].replace('Z', '+00:00')).timestamp()
                    corr.append(r)
    corr.sort(key=lambda r: (r['_at'], r['correction_id']))
    applied = 0
    voided = set()
    for r in corr:
        if r['_at'] > cutoff:
            continue
        k = (r['site'], r['punch_id'])
        act = r['action'].lower()
        if act == 'void':
            if k in punches and k not in voided:
                voided.add(k)
                del punches[k]
                applied += 1
        elif act == 'set':
            if k in punches:
                punches[k][2] = int(datetime.fromisoformat(r['time'].replace('Z', '+00:00')).timestamp())
                applied += 1
        elif act == 'add':
            if k not in ever and r['site'] in sites:
                ts = int(datetime.fromisoformat(r['time'].replace('Z', '+00:00')).timestamp())
                punches[k] = [r['employee'], r['type'].upper(), ts]
                ever.add(k)
                applied += 1

    # group per employee
    per = {}
    for (site, pid), (emp, dr, ts) in punches.items():
        if emp in employees:
            per.setdefault(emp, []).append((ts, 0 if dr == 'OUT' else 1, site, pid, dr))

    stats = {e: dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0, gross=Fraction(0))
             for e in employees}
    exc = dict(open_shifts=0, orphan_outs=0, duplicates_dropped=0, corrections_applied=applied)

    for emp, lst in per.items():
        hz = sites[employees[emp]][0]
        lst.sort()
        kept = []
        last = None
        for ts, _, site, pid, dr in lst:
            r = round_punch(ts, sites[site][0])
            if last is not None and last[1] == dr and ts - last[0] <= 300:
                wd = local_date(r, hz)
                if pstart <= wd <= pend:
                    exc['duplicates_dropped'] += 1
                continue
            last = (ts, dr)
            kept.append((r, dr, site))
        shifts = []
        cur = None

        def open_shift(p):
            if pstart <= local_date(p[0], hz) <= pend:
                exc['open_shifts'] += 1

        for p in kept:
            if p[1] == 'IN':
                if cur:
                    open_shift(cur)
                cur = p
            else:
                if cur and p[0] - cur[0] <= 16 * 3600:
                    shifts.append((cur, p))
                else:
                    if pstart <= local_date(p[0], hz) <= pend:
                        exc['orphan_outs'] += 1
                    if cur:
                        open_shift(cur)
                cur = None
        if cur:
            open_shift(cur)

        rows = []
        for i, o in shifts:
            wd = local_date(i[0], hz)
            if not (pstart <= wd <= pend):
                continue
            worked = max(0, (o[0] - i[0]) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_minutes(i[0], o[0], sites[i[2]][0]), paid)
            rows.append((i[0], wd, paid, night))
        rows.sort()
        daily = {}
        weekly = {}
        st = stats[emp]
        rl = rates.get(emp, [])
        for _, wd, paid, night in rows:
            before = daily.get(wd, 0)
            daily[wd] = before + paid
            dot = max(0, before + paid - max(before, 480))
            nonot = paid - dot
            wk = wd - timedelta(days=wd.weekday())
            wb = weekly.get(wk, 0)
            weekly[wk] = wb + nonot
            wot = max(0, wb + nonot - max(wb, 2400))
            ot = dot + wot
            reg = paid - ot
            rate = Fraction(0)
            for ef, rv in rl:
                if ef <= wd:
                    rate = rv
            st['shifts'] += 1
            st['paid_minutes'] += paid
            st['overtime_minutes'] += ot
            st['night_minutes'] += night
            st['gross'] += rate * (reg + Fraction(3, 2) * ot) / 60 + rate * Fraction(15, 100) * night / 60

    def money(fr):
        cents = int((fr * 100 + Fraction(1, 2)) // 1)
        return '%d.%02d' % divmod(cents, 100)

    res_emps = {}
    tot = dict(shifts=0, paid_minutes=0, overtime_minutes=0, night_minutes=0)
    totcents = 0
    for e in sorted(employees):
        s = dict(stats[e])
        g = money(s['gross'])
        totcents += int(g.replace('.', ''))
        s['gross'] = g
        for k in tot:
            tot[k] += s[k]
        res_emps[e] = s
    tot['gross'] = '%d.%02d' % divmod(totcents, 100)
    out = dict(period=dict(start=period['start'], end=period['end']), employees=res_emps,
               exceptions=exc, totals=tot)
    with open(outp, 'w') as f:
        json.dump(out, f, indent=1)


main()
